import { Component, computed, input } from '@angular/core';
import type { EChartsOption } from 'echarts';
import { HrmChart } from './hrm-chart';

/** 1 bậc phễu: tên bước + số lượng. */
export interface HrmFunnelStage {
  name: string;
  value: number;
}

/** hrm-recruitment-funnel — phễu tuyển dụng: số ứng viên rơi rớt qua từng bước
 *  (Ứng tuyển → Sàng lọc → Phỏng vấn → Offer → Nhận việc). Rộng dần thu hẹp = tỉ lệ chuyển đổi.
 *  Domain HRM: tuyển dụng, phễu bán hàng, phễu onboarding. */
@Component({
  selector: 'hrm-recruitment-funnel',
  imports: [HrmChart],
  template: `<hrm-chart [option]="option()" [height]="height()" />`,
  host: { class: 'hrm-recruitment-funnel' },
})
export class HrmRecruitmentFunnel {
  /** Các bậc phễu, truyền theo thứ tự rộng → hẹp. */
  readonly stages = input<HrmFunnelStage[]>([]);
  /** Hiện số + % trên mỗi bậc. */
  readonly showValue = input(true);
  readonly height = input(320);

  protected readonly option = computed<EChartsOption>(() => {
    const s = this.stages();
    const top = Math.max(...s.map((x) => x.value), 1);
    return {
      tooltip: { trigger: 'item', formatter: '{b}: {c}' },
      legend: { bottom: 0 },
      series: [{
        type: 'funnel',
        top: 10, bottom: 40, left: '8%', right: '8%',
        minSize: '24%', gap: 2, sort: 'descending',
        label: { show: this.showValue(), formatter: (p: { name?: string; value?: number }) => `${p.name} ${p.value} (${Math.round(((p.value ?? 0) / top) * 100)}%)` },
        labelLine: { show: false },
        itemStyle: { borderWidth: 0 },
        data: s.map((x) => ({ name: x.name, value: x.value })),
      }],
    } as EChartsOption;
  });
}
